-- Автопостинг, крок 4: Reels «Кінетичний текст» (відео з реальних рендерів через ffmpeg, публікація REELS)
UPDATE content_templates SET status = 'trial', slots = '2–5 кадрів по 3 с (наїзд камери), рядок ≤38 симв. на кадр (перший — хук), фінал + CTA, звук з матеріалів або тиша, підпис' WHERE key = 'reel-kinetic';
INSERT INTO changelog (title, body, created_at) VALUES ('Автопостинг: Reels з рендерів', 'Контент → Пости → «+ ідея», формат «Reels» → відкрий пост: познач 2–5 кадрів (рендери, планування), впиши рядок на кожен кадр (перший — хук) і фінал — або «Джері, заповни тексти» (рядки під кадри + підпис). «Зібрати» — система робить відео 9:16 на ~10–16 с: кожен кадр 3 с з повільним наїздом камери, текст виїжджає знизу, мʼякі переходи, фінал — смарагдова картка з кнопкою і лого. Збірка ~20–60 с. Нічого не домальовується — тільки рух реальних кадрів. Звук: свій mp3 з папки матеріалів (з ліцензією) або без звуку; додати музику з бібліотеки Instagram через API не можна. «На апрув» — відео приходить у Telegram з ✓ / ✕, після ✓ виходить в Instagram як Reels (і в стрічку).', datetime('now'));
